+import { inputToRecipient, splitBySeparator } from '../../lib/mail/recipient';
+
+describe('address input', () => {
+    it('splits mixed separators into ordered, nonempty, unbracketed tokens', () => {
+        expect(
+            splitBySeparator(' , <plus@debye.proton.black>, ; visionary@debye.proton.black; <pro@debye.proton.black>, ')
+        ).toEqual(['plus@debye.proton.black', 'visionary@debye.proton.black', 'pro@debye.proton.black']);
+    });
+
+    it('uses a plain email for both recipient fields', () => {
+        expect(inputToRecipient('person@example.com')).toEqual({
+            Name: 'person@example.com',
+            Address: 'person@example.com',
+        });
+    });
+
+    it('uses a bare email for both recipient fields when input is bracketed', () => {
+        expect(inputToRecipient('<person@example.com>')).toEqual({
+            Name: 'person@example.com',
+            Address: 'person@example.com',
+        });
+    });
+});

